import{_ as t,r as a,c as o,d as i,a as n,o as r}from"./app-VPPMr0U6.js";const c={},p=n('<p>你好呀，我是苍何！</p><p>欢迎来到面试系列！这篇文章主要讲 PmHub 中如何利用 Seata 分布式事务来保证任务审批状态一致性。</p><p>分布式事务是历年来面试最喜欢问的，但我看网上教程都是偏理论的多，联系实际项目的少，而面试最喜欢的是拿着项目拷打。我们的目标是理论联系实际，让你少走弯路~</p><p>所以通过本章的学习，让你一次性理解分布式事务，并教你在 PmHub 中如何用好分布式事务，可谓是从道到术，卷起来吧，少年！！</p><p>本章可谓是干货满满，面试中也是重中之重，以下描述你可以直接写进简历，也可以根据你的理解进行优化。</p><ul><li>为保证任务审批状态的一致性，采用 Seata 分布式事务的 AT 模式</li></ul><figure><img src="https://cdn.tobebetterjavaer.com/stutymore/20240807212225.png" alt="超级硬核教程：八股+项目实战" tabindex="0" loading="lazy"><figcaption>超级硬核教程：八股+项目实战</figcaption></figure><h2 id="事务" tabindex="-1"><a class="header-anchor" href="#事务"><span>事务</span></a></h2><p>我们先想象一个场景： 假设用户A向用户B转账100元，这个操作包括以下步骤：</p><ol><li>从用户A的账户中扣减100元。</li><li>向用户B的账户中增加100元。 这两个步骤要么都成功，要么都失败。如果在步骤1扣减了100元，但步骤2增加时发生了错误，我们希望，用户A的账户金额恢复到原来的状态。</li></ol><p>上面是一个典型的事务场景，什么是事务？，简而言之，事务是逻辑上的一组操作，要么都执行，要么都不执行。</p><p>下面有一道经典的八股，衡量事务的四大特性的了解程度，理解的背一下就好了。</p><p>事务的四大特性（ACID）</p><ol><li>原子性（Atomicity）： ○ 事务中的所有操作要么全部成功，要么全部失败。即使在系统故障的情况下，事务也能保证不会只执行一部分操作。 ○ 例子：银行转账操作中，从一个账户扣钱并在另一个账户加钱，这两步操作要么都成功，要么都失败。</li><li>一致性（Consistency）： ○ 事务执行前后，数据库都必须处于一致的状态。所有事务必须使数据库从一个一致状态变换到另一个一致状态。 ○ 例子：转账后，两个账户的总金额应该保持不变。</li><li>隔离性（Isolation）： ○ 并发事务之间互不影响，一个事务的中间状态对其他事务不可见。不同事务之间的操作是相互独立的。 ○ 例子：同时进行的两个转账操作不会互相干扰，每个操作都看不到对方的中间状态。</li><li>持久性（Durability）： ○ 一旦事务提交，其结果是永久性的，即使系统崩溃，事务的结果也不会丢失。 ○ 例子：转账成功后，系统崩溃重启，账户金额的变动依然存在</li></ol>',14);function l(s,m){const e=a("PaidContentBanner");return r(),o("div",null,[p,i(e)])}const d=t(c,[["render",l],["__file","pmhub-seata-consistency.html.vue"]]),h=JSON.parse('{"path":"/pmhub/interview/pmhub-seata-consistency.html","title":"PmHub分布式事务Seata保证任务审批状态一致性（👍必看）","lang":"zh-CN","frontmatter":{"title":"PmHub分布式事务Seata保证任务审批状态一致性（👍必看）","shortTitle":"PmHub整合Seata实现分布式事务","date":"2024-08-07T06:38:56.000Z","categories":["PmHub","面试系列"],"requiresAuth":true,"description":"PmHub 拆分了用户、流程、项目管理、认证等 4 个微服务，整合了 Redis 缓存、RocketMQ 消息队列、Docker 容器、Jenkins 自动化部署、Spring Security 安全框架、Nacos 服务注册和发现、Spring Boot Actuator 服务监控、Skywalking 链路追踪、Sentinel 熔断降级、Seata 分布式事务、Vue 前端框架等互联网开发中需要用到的绝大多数主流技术栈。","head":[["meta",{"name":"keywords","content":"PmHub,Spring  Cloud,微服务,AI,知识星球,沉默王二,二哥的Java进阶之路,二哥的编程星球,Java进阶之路,编程,Java,IT,计算机专业,付费专栏,实战项目,分布式"}],["meta",{"property":"og:url","content":"https://laigeoffer.cn/pmhub/interview/pmhub-seata-consistency.html"}],["meta",{"property":"og:site_name","content":"来个offer"}],["meta",{"property":"og:title","content":"PmHub分布式事务Seata保证任务审批状态一致性（👍必看）"}],["meta",{"property":"og:description","content":"PmHub 拆分了用户、流程、项目管理、认证等 4 个微服务，整合了 Redis 缓存、RocketMQ 消息队列、Docker 容器、Jenkins 自动化部署、Spring Security 安全框架、Nacos 服务注册和发现、Spring Boot Actuator 服务监控、Skywalking 链路追踪、Sentinel 熔断降级、Seata 分布式事务、Vue 前端框架等互联网开发中需要用到的绝大多数主流技术栈。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://cdn.tobebetterjavaer.com/stutymore/20240807212225.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2024-08-09T02:48:07.000Z"}],["meta",{"property":"article:author","content":"苍何&沉默王二"}],["meta",{"property":"article:published_time","content":"2024-08-07T06:38:56.000Z"}],["meta",{"property":"article:modified_time","content":"2024-08-09T02:48:07.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"PmHub分布式事务Seata保证任务审批状态一致性（👍必看）\\",\\"image\\":[\\"https://cdn.tobebetterjavaer.com/stutymore/20240807212225.png\\"],\\"datePublished\\":\\"2024-08-07T06:38:56.000Z\\",\\"dateModified\\":\\"2024-08-09T02:48:07.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"苍何&沉默王二\\",\\"url\\":\\"https://github.com/laigeoffer\\"}]}"]]},"headers":[{"level":2,"title":"事务","slug":"事务","link":"#事务","children":[]}],"git":{"createdTime":1723047302000,"updatedTime":1723171687000,"contributors":[{"name":"canghe","email":"2689458656@qq.com","commits":2}]},"readingTime":{"minutes":3.22,"words":966},"filePathRelative":"pmhub/interview/pmhub-seata-consistency.md","localizedDate":"2024年8月7日"}');export{d as comp,h as data};
